  "keyRelationCoverage": [
    {
      "element": "주식회사의 법인격은 주주들이 개인 재산을 출연해 부여하는 것이 아니라 구성원 단체에 부여된다.",
      "covered": false,
      "observationId": "",
      "quote": ""
